function verify(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}function one(PDO $p,string $q,array $a=[]):array{$s=$p->prepare($q);$s->execute($a);return $s->fetch()?:[];}function scalar(PDO $p,string $q,array $a=[]):string{$s=$p->prepare($q);$s->execute($a);return(string)$s->fetchColumn();}
function expectFail(PDO $p,string $sql,string $message):void{try{$p->exec($sql);throw new RuntimeException($message);}catch(PDOException $e){verify($e->getCode()!=='00000',$message);}}function user(PDO $p,string $email,string $name):array{$s=$p->prepare("INSERT INTO users(email,password,name,plan,email_verified_at) VALUES(?,'disabled',?,'Free',NOW())");$s->execute([$email,$name]);return['id'=>(int)$p->lastInsertId(),'name'=>$name];}
function column(PDO $p,string $t,string $c,string $type,bool $nullable):void{$r=one($p,'SELECT DATA_TYPE,IS_NULLABLE FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?',[$t,$c]);verify(($r['DATA_TYPE']??'')===$type&&(($r['IS_NULLABLE']??'')==='YES')===$nullable,"Invalid column $t.$c");}function fk(PDO $p,string $t,string $c,string $target,string $rule):void{$r=one($p,"SELECT k.REFERENCED_TABLE_NAME,r.DELETE_RULE FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME=? AND k.COLUMN_NAME=? AND k.REFERENCED_TABLE_NAME IS NOT NULL",[$t,$c]);verify(($r['REFERENCED_TABLE_NAME']??'')===$target&&($r['DELETE_RULE']??'')===$rule,"Invalid FK $t.$c");}
